import{_ as i,a0 as t,w as o,s as r,ao as d,I as l,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"ARMv8 上的 kprobes 事件跟蹤 | LCTT x X-CMD","titleTemplate":false,"description":"ARMv8 上的 kprobes 事件跟蹤 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ARMv8 上的 kprobes 事件跟蹤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ARMv8 上的 kprobes 事件跟蹤 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20161216 Kprobes Event Tracing on ARMv8","title":"ARMv8 上的 kprobes 事件跟蹤","tag":"201712","desc":""},"relativePath":"201712/20161216 Kprobes Event Tracing on ARMv8.md","filePath":"[post].md"}'),f={name:"201712/20161216 Kprobes Event Tracing on ARMv8.md"};function c(b,s,g,h,k,x){const n=t("Link");return o(),r("div",null,[s[16]||(s[16]=d(`<h1 id="armv8-上的-kprobes-事件跟蹤" tabindex="-1">ARMv8 上的 kprobes 事件跟蹤 <a class="header-anchor" href="#armv8-上的-kprobes-事件跟蹤" aria-label="Permalink to “ARMv8 上的 kprobes 事件跟蹤”">​</a></h1><p><img src="http://www.linaro.org/wp-content/uploads/2016/02/core-dump.png" alt="core-dump"></p><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>kprobes 是一種內核功能，它允許通過在執行（或模擬）斷點指令之前和之後，設置調用開發者提供例程的任意斷點來檢測內核。可參見 kprobes 文檔^注1 獲取更多信息。基本的 kprobes 功能可使用 <code>CONFIG_KPROBEES</code> 來選擇。在 arm64 的 v4.8 內核發行版中， kprobes 支持被添加到主線。</p><p>在這篇文章中，我們將介紹 kprobes 在 arm64 上的使用，通過在命令列中使用 debugfs 事件追蹤接口來收集動態追蹤事件。這個功能在一些架構（包括 arm32）上可用已經有段時間，現在在 arm64 上也能使用了。這個功能可以無需編寫任何代碼就能使用 kprobes。</p><h3 id="探針類型" tabindex="-1">探針類型 <a class="header-anchor" href="#探針類型" aria-label="Permalink to “探針類型”">​</a></h3><p>kprobes 子系統提供了三種不同類型的動態探針，如下所述。</p><h4 id="kprobes" tabindex="-1">kprobes <a class="header-anchor" href="#kprobes" aria-label="Permalink to “kprobes”">​</a></h4><p>基本探針是 kprobes 插入的一個軟件斷點，用以替代你正在探測的指令，當探測點被命中時，它為最終的單步執行（或模擬）保存下原始指令。</p><h4 id="kretprobes" tabindex="-1">kretprobes <a class="header-anchor" href="#kretprobes" aria-label="Permalink to “kretprobes”">​</a></h4><p>kretprobes 是 kprobes 的一部分，它允許攔截返回函數，而不必在返回點設置一個探針（或者可能有多個探針）。對於支持的架構（包括 ARMv8），只要選擇 kprobes，就可以選擇此功能。</p><h4 id="jprobes" tabindex="-1">jprobes <a class="header-anchor" href="#jprobes" aria-label="Permalink to “jprobes”">​</a></h4><p>jprobes 允許通過提供一個具有相同<ruby>調用簽名<rt>call signature</rt></ruby>的中間函數來攔截對一個函數的調用，這裏中間函數將被首先調用。jprobes 只是一個編程接口，它不能通過 debugfs 事件追蹤子系統來使用。因此，我們將不會在這裏進一步討論 jprobes。如果你想使用 jprobes，請參考 kprobes 文檔。</p><h3 id="調用-kprobes" tabindex="-1">調用 kprobes <a class="header-anchor" href="#調用-kprobes" aria-label="Permalink to “調用 kprobes”">​</a></h3><p>kprobes 提供一系列能從內核代碼中調用的 API 來設置探測點和當探測點被命中時調用的註冊函數。在不往內核中添加代碼的情況下，kprobes 也是可用的，這是通過寫入特定事件追蹤的 debugfs 文件來實現的，需要在文件中設置探針地址和信息，以便在探針被命中時記錄到追蹤日誌中。後者是本文將要討論的重點。最後 kprobes 可以通過 perl 命令來使用。</p><h4 id="kprobes-api" tabindex="-1">kprobes API <a class="header-anchor" href="#kprobes-api" aria-label="Permalink to “kprobes API”">​</a></h4><p>內核開發人員可以在內核中編寫函數(通常在專用的調試模組中完成）來設置探測點，並且在探測指令執行前和執行後立即執行任何所需操作。這在 kprobes.txt 中有很好的解釋。</p><h4 id="事件追蹤" tabindex="-1">事件追蹤 <a class="header-anchor" href="#事件追蹤" aria-label="Permalink to “事件追蹤”">​</a></h4><p>事件追蹤子系統有自己的自己的文檔^注2 ，對於瞭解一般追蹤事件的背景可能值得一讀。事件追蹤子系統是<ruby>追蹤點<rt>tracepoints</rt></ruby>和 kprobes 事件追蹤的基礎。事件追蹤文檔重點關注追蹤點，所以請在查閲文檔時記住這一點。kprobes 與追蹤點不同的是沒有預定義的追蹤點列表，而是採用動態創建的用於觸發追蹤事件信息收集的任意探測點。事件追蹤子系統通過一系列 debugfs 文件來控制和監視。事件追蹤（<code>CONFIG_EVENT_TRACING</code>）將在被如 kprobe 事件追蹤子系統等需要時自動選擇。</p><h5 id="kprobes-事件" tabindex="-1">kprobes 事件 <a class="header-anchor" href="#kprobes-事件" aria-label="Permalink to “kprobes 事件”">​</a></h5><p>使用 kprobes 事件追蹤子系統，用户可以在內核任意斷點處指定要報告的信息，只需要指定任意現有可探測指令的地址以及格式化信息即可確定。在執行過程中遇到斷點時，kprobes 將所請求的信息傳遞給事件追蹤子系統的公共部分，這些部分將數據格式化並追加到追蹤日誌中，就像追蹤點的工作方式一樣。kprobes 使用一個類似的但是大部分是獨立的 debugfs 文件來控制和顯示追蹤事件信息。該功能可使用 <code>CONFIG_KPROBE_EVENT</code> 來選擇。Kprobetrace 文檔^ 注3 提供瞭如何使用 kprobes 事件追蹤的基本信息，並且應當被參考用以瞭解以下介紹示例的詳細信息。</p><h4 id="kprobes-和-perf" tabindex="-1">kprobes 和 perf <a class="header-anchor" href="#kprobes-和-perf" aria-label="Permalink to “kprobes 和 perf”">​</a></h4><p>perf 工具為 kprobes 提供了另一個命令列接口。特別地，<code>perf probe</code> 允許探測點除了由函數名加偏移量和地址指定外，還可由源文件和行號指定。perf 接口實際上是使用 kprobes 的 debugfs 接口的封裝器。</p><h3 id="arm64-kprobes" tabindex="-1">Arm64 kprobes <a class="header-anchor" href="#arm64-kprobes" aria-label="Permalink to “Arm64 kprobes”">​</a></h3><p>上述所有 kprobes 的方面現在都在 arm64 上得到實現，然而實際上與其它架構上的有一些不同：</p><ul><li>註冊名稱參數當然是依架構而特定的，並且可以在 ARM ARM 中找到。</li><li>目前不是所有的指令類型都可被探測。當前不可探測的指令包括 mrs/msr（除了 DAIF 讀取）、異常生成指令、eret 和 hint（除了 nop 變體）。在這些情況下，只探測一個附近的指令來代替是最簡單的。這些指令在探測的黑名單裏是因為在 kprobes 單步執行或者指令模擬時它們對處理器狀態造成的改變是不安全的，這是由於 kprobes 構造的單步執行上下文和指令所需要的不一致，或者是由於指令不能容忍在 kprobes 中額外的處理時間和異常處理（ldx/stx）。</li><li>試圖識別在 ldx/stx 序列中的指令並且防止探測，但是理論上這種檢查可能會失敗，導致允許探測到的原子序列永遠不會成功。當探測原子代碼序列附近時應該小心。</li><li>注意由於 linux ARM64 調用約定的具體信息，為探測函數可靠地複製棧幀是不可能的，基於此不要試圖用 jprobes 這樣做，這一點與支持 jprobes 的大多數其它架構不同。這樣的原因是被調用者沒有足夠的信息來確定需要的棧數量。</li><li>注意當探針被命中時，一個探針記錄的棧指針信息將反映出使用中的特定棧指針，它是內核棧指針或者中斷棧指針。</li><li>有一組內核函數是不能被探測的，通常因為它們作為 kprobes 處理的一部分被調用。這組函數的一部分是依架構特定的，並且也包含如異常入口代碼等。</li></ul><h3 id="使用-kprobes-事件追蹤" tabindex="-1">使用 kprobes 事件追蹤 <a class="header-anchor" href="#使用-kprobes-事件追蹤" aria-label="Permalink to “使用 kprobes 事件追蹤”">​</a></h3><p>kprobes 的一個常用例子是檢測函數入口和/或出口。因為只需要使用函數名來作為探針地址，它安裝探針特別簡單。kprobes 事件追蹤將查看符號名稱並且確定地址。ARMv8 調用標準定義了函數參數和返回值的位置，並且這些可以作為 kprobes 事件處理的一部分被打印出來。</p><h4 id="例子-函數入口探測" tabindex="-1">例子: 函數入口探測 <a class="header-anchor" href="#例子-函數入口探測" aria-label="Permalink to “例子: 函數入口探測”">​</a></h4><p>檢測 USB 以太網驅動程序復位功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/sys/kernel/debug/tracing</span></span>
<span class="line"><span>$ cat &gt; kprobe_events &lt;&lt;EOF</span></span>
<span class="line"><span>p ax88772_reset %x0</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>$ echo 1 &gt; events/kprobes/enable</span></span></code></pre></div><p>此時每次該驅動的 <code>ax8872_reset()</code> 函數被調用，追蹤事件都將會被記錄。這個事件將顯示指向通過作為此函數的唯一參數的 <code>X0</code>（按照 ARMv8 調用標準）傳入的 <code>usbnet</code> 結構的指針。插入需要以太網驅動程序的 USB 加密狗後，我們看見以下追蹤信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat trace</span></span>
<span class="line"><span># tracer: nop</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># entries-in-buffer/entries-written: 1/1   #P:8</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>#                           _—–=&gt; irqs-off</span></span>
<span class="line"><span>#                          / _—-=&gt; need-resched</span></span>
<span class="line"><span>#                         | / _—=&gt; hardirq/softirq</span></span>
<span class="line"><span>#                         || / _–=&gt; preempt-depth</span></span>
<span class="line"><span>#                         ||| / delay</span></span>
<span class="line"><span>#        TASK-PID   CPU#  |||| TIMESTAMP  FUNCTION</span></span>
<span class="line"><span>#           | |    |   ||||    |      |</span></span>
<span class="line"><span>kworker/0:0-4             [000] d… 10972.102939:   p_ax88772_reset_0:</span></span>
<span class="line"><span>(ax88772_reset+0x0/0x230)   arg1=0xffff800064824c80</span></span></code></pre></div><p>這裏我們可以看見傳入到我們的探測函數的指針參數的值。由於我們沒有使用 kprobes 事件追蹤的可選標籤功能，我們需要的信息自動被標註為 <code>arg1</code>。注意這指向我們需要 kprobes 記錄這個探針的一組值的第一個，而不是函數參數的實際位置。在這個例子中它也只是碰巧是我們探測函數的第一個參數。</p><h4 id="例子-函數入口和返回探測" tabindex="-1">例子: 函數入口和返回探測 <a class="header-anchor" href="#例子-函數入口和返回探測" aria-label="Permalink to “例子: 函數入口和返回探測”">​</a></h4><p>kretprobe 功能專門用於探測函數返回。在函數入口 kprobes 子系統將會被調用並且建立鈎子以便在函數返回時調用，鈎子將記錄需求事件信息。對最常見情況，返回信息通常在 <code>X0</code> 寄存器中，這是非常有用的。在 <code>%x0</code> 中返回值也可以被稱為 <code>$retval</code>。以下例子也演示瞭如何提供一個可讀的標籤來展示有趣的信息。</p><p>使用 kprobes 和 kretprobe 檢測內核 <code>do_fork()</code> 函數來記錄參數和結果的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /sys/kernel/debug/tracing</span></span>
<span class="line"><span>$ cat &gt; kprobe_events &lt;&lt;EOF</span></span>
<span class="line"><span>p _do_fork %x0 %x1 %x2 %x3 %x4 %x5</span></span>
<span class="line"><span>r _do_fork pid=%x0</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>$ echo 1 &gt; events/kprobes/enable</span></span></code></pre></div><p>此時每次對 <code>_do_fork()</code> 的調用都會產生兩個記錄到 trace 文件的 kprobe 事件，一個報告調用參數值，另一個報告返回值。返回值在 trace 文件中將被標記為 <code>pid</code>。這裏是三次 fork 系統調用執行後的 trace 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>_$ cat trace</span></span>
<span class="line"><span># tracer: nop</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># entries-in-buffer/entries-written: 6/6   #P:8</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>#                              _—–=&gt; irqs-off</span></span>
<span class="line"><span>#                             / _—-=&gt; need-resched</span></span>
<span class="line"><span>#                            | / _—=&gt; hardirq/softirq</span></span>
<span class="line"><span>#                            || / _–=&gt; preempt-depth</span></span>
<span class="line"><span>#                            ||| /     delay</span></span>
<span class="line"><span>#           TASK-PID   CPU#  ||||    TIMESTAMP  FUNCTION</span></span>
<span class="line"><span>#              | |       |   ||||       |         |</span></span>
<span class="line"><span>              bash-1671  [001] d…   204.946007: p__do_fork_0: (_do_fork+0x0/0x3e4) arg1=0x1200011 arg2=0x0 arg3=0x0 arg4=0x0 arg5=0xffff78b690d0 arg6=0x0</span></span>
<span class="line"><span>              bash-1671  [001] d..1   204.946391: r__do_fork_0: (SyS_clone+0x18/0x20 &lt;- _do_fork) pid=0x724</span></span>
<span class="line"><span>              bash-1671  [001] d…   208.845749: p__do_fork_0: (_do_fork+0x0/0x3e4) arg1=0x1200011 arg2=0x0 arg3=0x0 arg4=0x0 arg5=0xffff78b690d0 arg6=0x0</span></span>
<span class="line"><span>              bash-1671  [001] d..1   208.846127: r__do_fork_0: (SyS_clone+0x18/0x20 &lt;- _do_fork) pid=0x725</span></span>
<span class="line"><span>              bash-1671  [001] d…   214.401604: p__do_fork_0: (_do_fork+0x0/0x3e4) arg1=0x1200011 arg2=0x0 arg3=0x0 arg4=0x0 arg5=0xffff78b690d0 arg6=0x0</span></span>
<span class="line"><span>              bash-1671  [001] d..1   214.401975: r__do_fork_0: (SyS_clone+0x18/0x20 &lt;- _do_fork) pid=0x726_</span></span></code></pre></div><h4 id="例子-解引用指針參數" tabindex="-1">例子： 解引用指針參數 <a class="header-anchor" href="#例子-解引用指針參數" aria-label="Permalink to “例子： 解引用指針參數”">​</a></h4><p>對於指針值，kprobes 事件處理子系統也允許解引用和打印所需的內存內容，適用於各種基本數據類型。為了展示所需字段，手動計算結構的偏移量是必要的。</p><p>檢測 <code>_do_wait()</code> 函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &gt; kprobe_events &lt;&lt;EOF</span></span>
<span class="line"><span>p:wait_p do_wait wo_type=+0(%x0):u32 wo_flags=+4(%x0):u32</span></span>
<span class="line"><span>r:wait_r do_wait $retval</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>$ echo 1 &gt; events/kprobes/enable</span></span></code></pre></div><p>注意在第一個探針中使用的參數標籤是可選的，並且可用於更清晰地識別記錄在追蹤日誌中的信息。帶符號的偏移量和括號表明了寄存器參數是指向記錄在追蹤日誌中的內存內容的指針。<code>:u32</code> 表明了內存位置包含一個無符號的 4 字節寬的數據（在這個例子中指局部定義的結構中的一個 emum 和一個 int）。</p><p>探針標籤（冒號後）是可選的，並且將用來識別日誌中的探針。對每個探針來説標籤必須是獨一無二的。如果沒有指定，將從附近的符號名稱自動生成一個有用的標籤，如前面的例子所示。</p><p>也要注意 <code>$retval</code> 參數可以只是指定為 <code>%x0</code>。</p><p>這裏是兩次 fork 系統調用執行後的 trace 文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat trace</span></span>
<span class="line"><span># tracer: nop</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># entries-in-buffer/entries-written: 4/4   #P:8</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>#                              _—–=&gt; irqs-off</span></span>
<span class="line"><span>#                             / _—-=&gt; need-resched</span></span>
<span class="line"><span>#                            | / _—=&gt; hardirq/softirq</span></span>
<span class="line"><span>#                            || / _–=&gt; preempt-depth</span></span>
<span class="line"><span>#                            ||| /     delay</span></span>
<span class="line"><span>#           TASK-PID   CPU#  ||||    TIMESTAMP  FUNCTION</span></span>
<span class="line"><span>#              | |       |   ||||       |         |</span></span>
<span class="line"><span>             bash-1702  [001] d…   175.342074: wait_p: (do_wait+0x0/0x260) wo_type=0x3 wo_flags=0xe</span></span>
<span class="line"><span>             bash-1702  [002] d..1   175.347236: wait_r: (SyS_wait4+0x74/0xe4 &lt;- do_wait) arg1=0x757</span></span>
<span class="line"><span>             bash-1702  [002] d…   175.347337: wait_p: (do_wait+0x0/0x260) wo_type=0x3 wo_flags=0xf</span></span>
<span class="line"><span>             bash-1702  [002] d..1   175.347349: wait_r: (SyS_wait4+0x74/0xe4 &lt;- do_wait) arg1=0xfffffffffffffff6</span></span></code></pre></div><h4 id="例子-探測任意指令地址" tabindex="-1">例子: 探測任意指令地址 <a class="header-anchor" href="#例子-探測任意指令地址" aria-label="Permalink to “例子: 探測任意指令地址”">​</a></h4><p>在前面的例子中，我們已經為函數的入口和出口插入探針，然而探測一個任意指令（除少數例外）是可能的。如果我們正在 C 函數中放置一個探針，第一步是查看代碼的彙編版本以確定我們要放置探針的位置。一種方法是在 vmlinux 文件上使用 gdb,並在要放置探針的函數中展示指令。下面是一個在 <code>arch/arm64/kernel/modules.c</code> 中 <code>module_alloc</code> 函數執行此操作的示例。在這種情況下，因為 gdb 似乎更喜歡使用弱符號定義，並且它是與這個函數關聯的存根代碼，所以我們從 System.map 中來獲取符號值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep module_alloc System.map</span></span>
<span class="line"><span>ffff2000080951c4 T module_alloc</span></span>
<span class="line"><span>ffff200008297770 T kasan_module_alloc</span></span></code></pre></div><p>在這個例子中我們使用了交叉開發工具，並且在我們的主機系統上調用 gdb 來檢查指令包含我們感興趣函數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ \${CROSS_COMPILE}gdb vmlinux</span></span>
<span class="line"><span>(gdb) x/30i 0xffff2000080951c4</span></span>
<span class="line"><span>        0xffff2000080951c4 &lt;module_alloc&gt;:    sub    sp, sp, #0x30</span></span>
<span class="line"><span>        0xffff2000080951c8 &lt;module_alloc+4&gt;:    adrp    x3, 0xffff200008d70000</span></span>
<span class="line"><span>        0xffff2000080951cc &lt;module_alloc+8&gt;:    add    x3, x3, #0x0</span></span>
<span class="line"><span>        0xffff2000080951d0 &lt;module_alloc+12&gt;:    mov    x5, #0x713             // #1811</span></span>
<span class="line"><span>        0xffff2000080951d4 &lt;module_alloc+16&gt;:    mov    w4, #0xc0              // #192</span></span>
<span class="line"><span>        0xffff2000080951d8 &lt;module_alloc+20&gt;:</span></span>
<span class="line"><span>              mov    x2, #0xfffffffff8000000    // #-134217728</span></span>
<span class="line"><span>        0xffff2000080951dc &lt;module_alloc+24&gt;:    stp    x29, x30, [sp,#16]         0xffff2000080951e0 &lt;module_alloc+28&gt;:    add    x29, sp, #0x10</span></span>
<span class="line"><span>        0xffff2000080951e4 &lt;module_alloc+32&gt;:    movk    x5, #0xc8, lsl #48</span></span>
<span class="line"><span>        0xffff2000080951e8 &lt;module_alloc+36&gt;:    movk    w4, #0x240, lsl #16</span></span>
<span class="line"><span>        0xffff2000080951ec &lt;module_alloc+40&gt;:    str    x30, [sp]         0xffff2000080951f0 &lt;module_alloc+44&gt;:    mov    w7, #0xffffffff        // #-1</span></span>
<span class="line"><span>        0xffff2000080951f4 &lt;module_alloc+48&gt;:    mov    x6, #0x0               // #0</span></span>
<span class="line"><span>        0xffff2000080951f8 &lt;module_alloc+52&gt;:    add    x2, x3, x2</span></span>
<span class="line"><span>        0xffff2000080951fc &lt;module_alloc+56&gt;:    mov    x1, #0x8000            // #32768</span></span>
<span class="line"><span>        0xffff200008095200 &lt;module_alloc+60&gt;:    stp    x19, x20, [sp,#32]         0xffff200008095204 &lt;module_alloc+64&gt;:    mov    x20, x0</span></span>
<span class="line"><span>        0xffff200008095208 &lt;module_alloc+68&gt;:    bl    0xffff2000082737a8 &lt;__vmalloc_node_range&gt;</span></span>
<span class="line"><span>        0xffff20000809520c &lt;module_alloc+72&gt;:    mov    x19, x0</span></span>
<span class="line"><span>        0xffff200008095210 &lt;module_alloc+76&gt;:    cbz    x0, 0xffff200008095234 &lt;module_alloc+112&gt;</span></span>
<span class="line"><span>        0xffff200008095214 &lt;module_alloc+80&gt;:    mov    x1, x20</span></span>
<span class="line"><span>        0xffff200008095218 &lt;module_alloc+84&gt;:    bl    0xffff200008297770 &lt;kasan_module_alloc&gt;</span></span>
<span class="line"><span>        0xffff20000809521c &lt;module_alloc+88&gt;:    tbnz    w0, #31, 0xffff20000809524c &lt;module_alloc+136&gt;</span></span>
<span class="line"><span>        0xffff200008095220 &lt;module_alloc+92&gt;:    mov    sp, x29</span></span>
<span class="line"><span>        0xffff200008095224 &lt;module_alloc+96&gt;:    mov    x0, x19</span></span>
<span class="line"><span>        0xffff200008095228 &lt;module_alloc+100&gt;:    ldp    x19, x20, [sp,#16]         0xffff20000809522c &lt;module_alloc+104&gt;:    ldp    x29, x30, [sp],#32</span></span>
<span class="line"><span>        0xffff200008095230 &lt;module_alloc+108&gt;:    ret</span></span>
<span class="line"><span>        0xffff200008095234 &lt;module_alloc+112&gt;:    mov    sp, x29</span></span>
<span class="line"><span>        0xffff200008095238 &lt;module_alloc+116&gt;:    mov    x19, #0x0               // #0</span></span></code></pre></div><p>在這種情況下，我們將在此函數中顯示以下源代碼行的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>p = __vmalloc_node_range(size, MODULE_ALIGN, VMALLOC_START,</span></span>
<span class="line"><span>VMALLOC_END, GFP_KERNEL, PAGE_KERNEL_EXEC, 0,</span></span>
<span class="line"><span>NUMA_NO_NODE, __builtin_return_address(0));</span></span></code></pre></div><p>……以及在此代碼行的函數調用的返回值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if (p &amp;&amp; (kasan_module_alloc(p, size) &lt; 0)) {</span></span></code></pre></div><p>我們可以在從調用外部函數的彙編代碼中識別這些。為了展示這些值，我們將在目標系統上的 <code>0xffff20000809520c</code> 和 <code>0xffff20000809521c</code> 處放置探針。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &gt; kprobe_events &lt;&lt;EOF</span></span>
<span class="line"><span>p 0xffff20000809520c %x0</span></span>
<span class="line"><span>p 0xffff20000809521c %x0</span></span>
<span class="line"><span>EOF</span></span>
<span class="line"><span>$ echo 1 &gt; events/kprobes/enable</span></span></code></pre></div><p>現在將一個以太網適配器加密狗插入到 USB 端口後，我們看到以下寫入追蹤日誌的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat trace</span></span>
<span class="line"><span># tracer: nop</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># entries-in-buffer/entries-written: 12/12   #P:8</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>#                           _—–=&gt; irqs-off</span></span>
<span class="line"><span>#                          / _—-=&gt; need-resched</span></span>
<span class="line"><span>#                         | / _—=&gt; hardirq/softirq</span></span>
<span class="line"><span>#                         || / _–=&gt; preempt-depth</span></span>
<span class="line"><span>#                         ||| / delay</span></span>
<span class="line"><span>#        TASK-PID   CPU#  |||| TIMESTAMP  FUNCTION</span></span>
<span class="line"><span>#           | |    |   ||||    |      |</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.200991: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff200001188000</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.201059: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.201115: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff200001198000</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.201157: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.227456: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff2000011a0000</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.227522: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.227579: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff2000011b0000</span></span>
<span class="line"><span>      systemd-udevd-2082  [000] d… 77.227635: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span>
<span class="line"><span>      modprobe-2097  [002] d… 78.030643: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff2000011b8000</span></span>
<span class="line"><span>      modprobe-2097  [002] d… 78.030761: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span>
<span class="line"><span>      modprobe-2097  [002] d… 78.031132: p_0xffff20000809520c: (module_alloc+0x48/0x98) arg1=0xffff200001270000</span></span>
<span class="line"><span>      modprobe-2097  [002] d… 78.031187: p_0xffff20000809521c: (module_alloc+0x58/0x98) arg1=0x0</span></span></code></pre></div><p>kprobes 事件系統的另一個功能是記錄統計信息，這可在 <code>inkprobe_profile</code> 中找到。在以上追蹤後，該文件的內容為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat kprobe_profile</span></span>
<span class="line"><span> p_0xffff20000809520c                                    6            0</span></span>
<span class="line"><span>p_0xffff20000809521c                                    6            0</span></span></code></pre></div><p>這表明我們設置的兩處斷點每個共發生了 8 次命中，這當然與追蹤日誌數據是一致的。在 kprobetrace 文檔中有更多 kprobe_profile 的功能描述。</p><p>也可以進一步過濾 kprobes 事件。用來控制這點的 debugfs 文件在 kprobetrace 文檔中被列出，然而它們內容的詳細信息大多在 trace events 文檔中被描述。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>現在，Linux ARMv8 對支持 kprobes 功能也和其它架構相當。有人正在做添加 uprobes 和 systemtap 支持的工作。這些功能/工具和其他已經完成的功能（如： perf、 coresight）允許 Linux ARMv8 用户像在其它更老的架構上一樣調試和測試性能。</p><hr><p>參考文獻</p><ul><li>注1： Jim Keniston, Prasanna S. Panchamukhi, Masami Hiramatsu. “Kernel Probes (kprobes).” <em>GitHub</em>. GitHub, Inc., 15 Aug. 2016. Web. 13 Dec. 2016.</li><li>注2： Ts’o, Theodore, Li Zefan, and Tom Zanussi. “Event Tracing.” <em>GitHub</em>. GitHub, Inc., 3 Mar. 2016. Web. 13 Dec. 2016.</li><li>注3： Hiramatsu, Masami. “Kprobe-based Event Tracing.” <em>GitHub</em>. GitHub, Inc., 18 Aug. 2016. Web. 13 Dec. 2016.</li></ul><hr>`,72)),l("p",null,[s[1]||(s[1]=a("作者簡介 ： ",-1)),e(n,{href:"http://www.linaro.org/author/david-long/"},{default:p(()=>[...s[0]||(s[0]=[a("David Long",-1)])]),_:1}),s[2]||(s[2]=a(" 在 Linaro Kernel - Core Development 團隊中擔任工程師。 在加入 Linaro 之前，他在商業和國防行業工作了數年，既做嵌入式實時工作又為Unix提供軟件開發工具。之後，在 Digital（又名 Compaq）公司工作了十幾年，負責 Unix 標準，C 編譯器和運行時庫的工作。之後 David 又去了一系列初創公司做嵌入式 Linux 和安卓系統，嵌入式定製操作系統和 Xen 虛擬化。他擁有 MIPS，Alpha 和 ARM 平台的經驗（等等）。他使用過從 1979 年貝爾實驗室 V6 開始的大部分Unix操作系統，並且長期以來一直是 Linux 用户和倡導者。他偶爾也因使用烙鐵和數字示波器調試設備驅動而知名。",-1))]),s[17]||(s[17]=l("hr",null,null,-1)),l("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"http://www.linaro.org/blog/kprobes-event-tracing-armv8/"},{default:p(()=>[...s[3]||(s[3]=[a("http://www.linaro.org/blog/kprobes-event-tracing-armv8/",-1)])]),_:1})]),l("p",null,[s[8]||(s[8]=a("作者：",-1)),e(n,{href:"http://www.linaro.org/author/david-long/"},{default:p(()=>[...s[5]||(s[5]=[a("David Long",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),e(n,{href:"https://github.com/kimii"},{default:p(()=>[...s[6]||(s[6]=[a("kimii",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[13]||(s[13]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const v=i(f,[["render",c]]);export{m as __pageData,v as default};
